  'n3-515': { ja: 'ただ見ているだけです。', zh: '我只是看看而已。' },
  'n3-516': { ja: '多少の雨なら大丈夫だ。', zh: '一點小雨沒關係。' },
  'n3-517': { ja: 'つい食べすぎてしまった。', zh: '一不小心就吃太多了。' },
