  'n3-521': { ja: 'ふと窓の外を見た。', zh: '不經意地看了看窗外。' },
  'n3-522': { ja: '本来は今日休みのはずだった。', zh: '本來今天應該是休假。' },
  'n3-523': { ja: 'まさか彼が犯人だったとは。', zh: '萬萬沒想到他竟然是犯人。' },
