  'n3-525': { ja: 'ここは元々学校だった。', zh: '這裡原本是學校。' },
  'n3-526': { ja: 'やはり彼が犯人だった。', zh: '果然他就是犯人。' },
  'n3-527': { ja: 'お正月には親戚がみんな祖父の家に集まる。', zh: '過年時親戚們都會聚到祖父家。' },
  'n3-528': { ja: '被害者は犯人の知り合いだったらしい。', zh: '被害者似乎是犯人的熟人。' },
  'n3-529': { ja: '彼女とは幼なじみで、同じ町で育った。', zh: '我和她是青梅竹馬，在同一個鎮上長大。' },
  'n3-530': { ja: '恋愛の悩みを姉に相談した。', zh: '跟姊姊商量了戀愛的煩惱。' },
  'n3-531': { ja: '駅で初恋の人に偶然会った。', zh: '在車站偶然遇到了初戀對象。' },
  'n3-532': { ja: '三年間ずっと片思いをしている。', zh: '已經單戀了整整三年。' },
  'n3-533': { ja: '失恋して一週間何も食べられなかった。', zh: '失戀後一個星期什麼都吃不下。' },
  'n3-534': { ja: '二人は去年から交際している。', zh: '兩人從去年開始交往。' },
  'n3-535': { ja: '姉が婚約したと聞いて驚いた。', zh: '聽說姊姊訂婚了，嚇了一跳。' },
  'n3-536': { ja: '両親は私が十歳のときに離婚した。', zh: '父母在我十歲時離婚了。' },
  'n3-537': { ja: '友人の結婚式でスピーチをした。', zh: '在朋友的婚禮上致詞。' },
  'n3-538': { ja: '二人は新婚旅行で北海道に行った。', zh: '兩人新婚旅行去了北海道。' },
  'n3-539': { ja: '花嫁のドレスがとてもきれいだった。', zh: '新娘的禮服非常漂亮。' },
  'n3-540': { ja: '花婿は緊張して手が震えていた。', zh: '新郎緊張得手在發抖。' },
  'n3-541': { ja: '社長夫人もパーティーに来られた。', zh: '社長夫人也來參加了派對。' },
  'n3-542': { ja: '彼は三人兄弟の長男だ。', zh: '他是三兄弟中的長子。' },
  'n3-543': { ja: '長女が今年小学校に入学した。', zh: '長女今年上了小學。' },
  'n3-544': { ja: '次男はまだ三歳で、よく泣く。', zh: '二兒子才三歲，很愛哭。' },
  'n3-545': { ja: '末っ子なので家族にかわいがられた。', zh: '因為是老么，很受家人疼愛。' },
  'n3-546': { ja: '一人っ子なので兄弟がうらやましかった。', zh: '因為是獨生子，很羨慕有兄弟姊妹的人。' },
  'n3-547': { ja: 'あの双子は顔がそっくりで見分けがつかない。', zh: '那對雙胞胎長得一模一樣，分辨不出來。' },
  'n3-548': { ja: '公園で親子がボール遊びをしている。', zh: '公園裡有親子在玩球。' },
  'n3-549': { ja: 'お盆には祖先のお墓参りに行く。', zh: '盂蘭盆節會去掃祖先的墓。' },
  'n3-550': { ja: 'この森を子孫に残したい。', zh: '想把這片森林留給後代子孫。' },
  'n3-551': { ja: '叔父は東京で小さな店を経営している。', zh: '叔叔在東京經營一家小店。' },
  'n3-552': { ja: '夏休みは叔母の家に泊まった。', zh: '暑假住在阿姨家。' },
  'n3-553': { ja: '甥の誕生日におもちゃを送った。', zh: '姪子生日時送了玩具給他。' },
  'n3-554': { ja: '姪はもう大学生になった。', zh: '姪女已經上大學了。' },
  'n3-555': { ja: 'このマンションには百の世帯が住んでいる。', zh: '這棟大樓住了一百戶人家。' },
  'n3-556': { ja: '祖父母との同居を始めて一年になる。', zh: '開始和祖父母同住已經一年了。' },
  'n3-557': { ja: '大学に入ってから一人暮らしをしている。', zh: '上大學後就一個人住。' },
  'n3-558': { ja: '住民の多くは高齢者だ。', zh: '居民大多是高齡者。' },
  'n3-559': { ja: '高齢者のための体操教室がある。', zh: '有為高齡者開設的體操教室。' },
  'n3-560': { ja: '少年は事件の夜に怪しい男を見たと言った。', zh: '少年說他在案發當晚看到了可疑的男子。' },
  'n3-561': { ja: '少女は母親の手を握って泣いていた。', zh: '少女握著母親的手哭泣著。' },
  'n3-562': { ja: '背の高い青年が道を教えてくれた。', zh: '一位高個子的青年幫我指了路。' },
  'n3-563': { ja: '中年になってから急に太り始めた。', zh: '進入中年後突然開始發胖。' },
  'n3-564': { ja: '幼児の手が届かない所に薬を置いてください。', zh: '請把藥放在幼兒拿不到的地方。' },
  'n3-565': { ja: '日本では十八歳で成人になる。', zh: '在日本十八歲就成年了。' },
  'n3-566': { ja: '未成年はお酒を飲んではいけない。', zh: '未成年人不可以喝酒。' },
  'n3-567': { ja: '彼女は私より三つ年上だ。', zh: '她比我大三歲。' },
  'n3-568': { ja: '年下の同僚にパソコンの使い方を教わった。', zh: '向比我年輕的同事學了電腦的用法。' },
  'n3-569': { ja: '彼とは同い年なので話しやすい。', zh: '和他同年，所以很好聊。' },
  'n3-570': { ja: 'あの二人は仲がいいことで有名だ。', zh: '那兩人以感情好出名。' },
  'n3-571': { ja: 'うちの犬と猫は仲良しだ。', zh: '我家的狗和貓感情很好。' },
  'n3-572': { ja: '兄弟喧嘩をして母に叱られた。', zh: '兄弟吵架被媽媽罵了。' },
  'n3-573': { ja: '昨日喧嘩した友達ともう仲直りした。', zh: '已經和昨天吵架的朋友和好了。' },
  'n3-574': { ja: '仕事の付き合いで毎晩帰りが遅い。', zh: '因為工作應酬每晚都很晚回家。' },
  'n3-575': { ja: '二人の友情は三十年も続いている。', zh: '兩人的友情已持續了三十年。' },
  'n3-576': { ja: '祖母は孫たちに愛情をたっぷり注いだ。', zh: '奶奶對孫子們傾注了滿滿的愛。' },
  'n3-577': { ja: '彼は隣のクラスの子に恋をした。', zh: '他愛上了隔壁班的同學。' },
  'n3-578': { ja: '震災の後、家族の絆が強くなった。', zh: '震災之後，家人間的羈絆變得更深了。' },
  'n3-579': { ja: 'あの日の出会いが私の人生を変えた。', zh: '那天的相遇改變了我的人生。' },
  'n3-580': { ja: '卒業式は友達との別れがつらかった。', zh: '畢業典禮上和朋友分別很難受。' },
  'n3-581': { ja: '二十年ぶりの再会に二人とも涙を流した。', zh: '睽違二十年的重逢讓兩人都流下了眼淚。' },
  'n3-582': { ja: '朝、近所の人に元気に挨拶した。', zh: '早上很有精神地向鄰居打招呼。' },
  'n3-583': { ja: '彼は深くお辞儀をして部屋を出た。', zh: '他深深一鞠躬後走出了房間。' },
  'n3-584': { ja: '試合の後、選手たちは握手をした。', zh: '比賽結束後選手們互相握手。' },
  'n3-585': { ja: '犬の世話は弟の仕事だ。', zh: '照顧狗是弟弟的工作。' },
  'n3-586': { ja: '彼は若いのに礼儀正しい。', zh: '他年紀輕輕卻很有禮貌。' },
  'n3-587': { ja: 'お客様には敬語を使いなさい。', zh: '對客人要使用敬語。' },
  'n3-588': { ja: '彼はいつも料理に文句を言う。', zh: '他總是對菜挑毛病。' },
  'n3-589': { ja: '人の悪口を言うのはやめなさい。', zh: '別再說別人的壞話了。' },
  'n3-590': { ja: '今のは冗談だから怒らないで。', zh: '剛才只是開玩笑，別生氣。' },
  'n3-591': { ja: '彼の証言には嘘が一つ混じっている。', zh: '他的證詞裡混了一個謊言。' },
  'n3-592': { ja: '嘘つきと呼ばれて彼は顔を赤くした。', zh: '被叫做騙子，他漲紅了臉。' },
  'n3-593': { ja: '遅刻の言い訳はもう聞きたくない。', zh: '不想再聽遲到的藉口了。' },
  'n3-594': { ja: 'それはお世辞だとすぐに分かった。', zh: '馬上就知道那是客套的恭維話。' },
  'n3-595': { ja: '学校はいじめの問題に真剣に取り組むべきだ。', zh: '學校應該認真處理霸凌問題。' },
  'n3-596': { ja: '子どもの頃、仲間外れにされたことがある。', zh: '小時候曾經被排擠過。' },
