  'n3-598': { ja: '彼を敵に回すと面倒なことになる。', zh: '與他為敵會很麻煩。' },
  'n3-599': { ja: '彼とは小学校からのライバルだ。', zh: '他是我從小學開始的競爭對手。' },
  'n3-600': { ja: '先生の恩は一生忘れない。', zh: '老師的恩情我一輩子不會忘記。' },
  'n3-601': { ja: 'お互いの意見をよく聞きましょう。', zh: '好好聽聽彼此的意見吧。' },
  'n3-602': { ja: 'あの二人は相性がとてもいい。', zh: '那兩人非常合得來。' },
  'n3-603': { ja: '職場の人間関係に悩んでいる。', zh: '為職場的人際關係煩惱。' },
  'n3-604': { ja: '人間は一人では生きていけない。', zh: '人無法獨自活下去。' },
  'n3-605': { ja: '彼の温かい人柄に多くの人が引かれる。', zh: '許多人被他溫暖的為人所吸引。' },
  'n3-606': { ja: '人の人格を否定するような言い方はよくない。', zh: '否定他人人格的說法是不對的。' },
