  'n3-615': { ja: '彼女は意志が強く、一度決めたら変えない。', zh: '她意志堅強，一旦決定就不會改變。' },
  'n3-616': { ja: '冗談ではなく本気で言っているんだ。', zh: '我不是開玩笑，是認真的。' },
  'n3-617': { ja: '彼の本心がどこにあるのか分からない。', zh: '不知道他真正的想法是什麼。' },
