  'n3-619': { ja: 'この町で育ったことを誇りに思う。', zh: '我以在這個城鎮長大為傲。' },
  'n3-620': { ja: '彼の言葉に自尊心が傷ついた。', zh: '他的話傷了我的自尊心。' },
  'n3-621': { ja: 'プライドが高くて人に頭を下げられない。', zh: '自尊心太強，無法向人低頭。' },
  'n3-622': { ja: '優秀な兄に劣等感を持っていた。', zh: '曾對優秀的哥哥抱有自卑感。' },
