  'n3-624': { ja: '彼女は思いやりのある優しい人だ。', zh: '她是個體貼溫柔的人。' },
  'n3-625': { ja: '彼の笑顔には親しみを感じる。', zh: '他的笑容讓人感到親切。' },
  'n3-626': { ja: '彼の妹はクラスで一番の美人だ。', zh: '他妹妹是班上最漂亮的。' },
  'n3-627': { ja: '目上の人には丁寧な言葉を使う。', zh: '對長輩要用有禮貌的措辭。' },
  'n3-628': { ja: '怠け者の弟は宿題をいつも後回しにする。', zh: '懶惰的弟弟總是把作業往後拖。' },
  'n3-629': { ja: '祖母は朝から晩まで動く働き者だった。', zh: '奶奶是個從早忙到晚的勤勞人。' },
  'n3-630': { ja: '妹は頑張り屋で、毎晩遅くまで勉強している。', zh: '妹妹很努力，每晚都讀書到很晚。' },
  'n3-631': { ja: '息子は恥ずかしがり屋で、人前で話せない。', zh: '兒子很害羞，不敢在人前說話。' },
