  'n3-633': { ja: '彼はお人好しなので、すぐ人に騙される。', zh: '他是個老好人，很容易被騙。' },
  'n3-634': { ja: '子どもたちのいたずらで窓ガラスが割れた。', zh: '孩子們的惡作劇把窗戶玻璃打破了。' },
  'n3-635': { ja: '皆さんの温かい言葉に感激しました。', zh: '大家溫暖的話語讓我很感激。' },
  'n3-636': { ja: '合格の喜びを家族と分かち合った。', zh: '和家人分享了考上的喜悅。' },
  'n3-637': { ja: '母を亡くした悲しみはなかなか消えない。', zh: '失去母親的悲痛久久無法消散。' },
  'n3-638': { ja: '彼は怒りで顔が真っ赤になった。', zh: '他氣得滿臉通紅。' },
  'n3-639': { ja: '病気の苦しみは本人にしか分からない。', zh: '疾病的痛苦只有本人才知道。' },
  'n3-640': { ja: '家族みんなが元気なのが一番の幸せだ。', zh: '家人都健康就是最大的幸福。' },
  'n3-641': { ja: '彼の家族に不幸が続いた。', zh: '他家接連發生不幸的事。' },
  'n3-642': { ja: '彼の話を聞いて、思わず同情してしまった。', zh: '聽了他的話，不禁同情起他來。' },
  'n3-643': { ja: '毎朝早く起きる息子に感心している。', zh: '很佩服每天早起的兒子。' },
