  'n3-651': { ja: '親友の嘘を知ってショックを受けた。', zh: '得知摯友的謊言而大受打擊。' },
  'n3-652': { ja: '映画の感想を聞かせてください。', zh: '請告訴我你對電影的感想。' },
  'n3-653': { ja: '今朝の父は機嫌が悪かった。', zh: '今天早上爸爸心情不好。' },
  'n3-654': { ja: '彼の話に会場は笑いに包まれた。', zh: '他的話讓會場充滿笑聲。' },
