  'n3-656': { ja: '彼女の微笑みに心が温かくなった。', zh: '她的微笑讓我心裡暖暖的。' },
  'n3-657': { ja: '隣の部屋から赤ちゃんの泣き声が聞こえる。', zh: '隔壁房間傳來嬰兒的哭聲。' },
