  'n3-2432': { ja: '衆院の選挙で与党が勝った。', zh: '執政黨在眾議院選舉中獲勝。' },
  'n3-2433': { ja: '内閣は責任を取って総辞職した。', zh: '內閣負起責任總辭。' },
  'n3-2434': { ja: '野党は内閣不信任の案を出した。', zh: '在野黨提出了內閣不信任案。' },
  'n3-2435': { ja: '首相は秋に内閣改造を行った。', zh: '首相在秋天進行了內閣改組。' },
