  'n3-2437': { ja: '中央銀行が政策金利を上げた。', zh: '中央銀行調升了政策利率。' },
  'n3-2438': { ja: '昔、この鉄道は国営だった。', zh: '這條鐵路以前是國營的。' },
  'n3-2439': { ja: '公営の住宅に申し込んだ。', zh: '申請了公營住宅。' },
  'n3-2440': { ja: '男は店員を殴り倒してレジのお金を奪った。', zh: '男子把店員打倒在地，搶走收銀機的錢。' },
  'n3-2441': { ja: '親分は子分を締め上げて裏切り者を探した。', zh: '老大嚴厲逼問手下，揪出叛徒。' },
  'n3-2442': { ja: '被害者は鋭い刃物で刺し殺されていた。', zh: '被害人是被銳利的刀刃刺死的。' },
  'n3-2443': { ja: '映画の中で主人公は敵を撃ち殺した。', zh: '電影中主角射殺了敵人。' },
  'n3-2444': { ja: '二人の話には大きな食い違いがある。', zh: '兩人的說法有很大的出入。' },
  'n3-2445': { ja: '彼の説明は辻褄が合わない。', zh: '他的說明前後矛盾。' },
  'n3-2446': { ja: '警察は容疑者の足取りを追っている。', zh: '警方正在追查嫌犯的行蹤。' },
  'n3-2447': { ja: 'それはライバル会社の策略だった。', zh: '那是對手公司的計謀。' },
  'n3-2448': { ja: '大学生のころ、親から毎月仕送りをもらっていた。', zh: '大學時每個月收到父母寄來的生活費。' },
  'n3-2449': { ja: '夫の稼ぎだけでは生活できない。', zh: '只靠丈夫的收入無法生活。' },
  'n3-2450': { ja: '勤め先の電話番号を書いてください。', zh: '請寫下工作單位的電話號碼。' },
  'n3-2451': { ja: 'この町には若者の働き口が少ない。', zh: '這個城鎮給年輕人的工作機會很少。' },
  'n3-2452': { ja: '雇い主に給料を上げてほしいと頼んだ。', zh: '拜託僱主幫我加薪。' },
  'n3-2453': { ja: '父は冬になると東京へ出稼ぎに行った。', zh: '爸爸一到冬天就去東京打工。' },
